// Prepare data: checks the two sheet reads, picks the latest weekly_snapshots row
// and works out the dates. Never throws: every problem goes into errors[] so the
// workflow sends a short alert to TEST_EMAIL instead of the e-mail to Scott.
const S = $('SETTINGS').first().json;
const TZ = S.TIMEZONE || 'America/Sao_Paulo';
const str = (v) => (v === null || v === undefined) ? '' : String(v).trim();
const errors = [];

// Same date rules as workflow B: serial number, AAAA-MM-DD or DD/MM/AAAA.
function toDateTime(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return DateTime.fromMillis(Math.round((v - 25569) * 86400000), { zone: 'UTC' }).setZone(TZ, { keepLocalTime: true });
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return DateTime.fromObject({ year: +m[1], month: +m[2], day: +m[3] }, { zone: TZ });
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return DateTime.fromObject({ year: +m[3], month: +m[2], day: +m[1] }, { zone: TZ });
  if (/^\d+(\.\d+)?$/.test(s)) return toDateTime(Number(s));
  return null;
}
function toISODate(v) { const d = toDateTime(v); return d && d.isValid ? d.toISODate() : ''; }

// Reads the output of a Google Sheets node (Continue on fail + Always output data).
function readSheet(nodeName, label) {
  let items;
  try { items = $(nodeName).all(); } catch (e) { errors.push(label + ': the node did not run (' + e.message + ').'); return null; }
  const failed = items.find(i => i.json && i.json.error);
  if (failed) {
    const e = failed.json.error;
    errors.push(label + ': read failed (' + str(typeof e === 'object' ? (e.message || JSON.stringify(e)) : e).slice(0, 300) + ').');
    return null;
  }
  return items.map(i => i.json).filter(r => r && Object.keys(r).some(k => k !== 'row_number' && str(r[k]) !== ''));
}

// ---------- settings
const MODE = str(S.MODE).toLowerCase();
if (MODE !== 'test' && MODE !== 'prod') errors.push('SETTINGS: MODE must be "test" or "prod" (it is "' + str(S.MODE) + '").');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(str(S.TEST_EMAIL))) errors.push('SETTINGS: TEST_EMAIL is not a valid e-mail address.');
if (MODE === 'prod' && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(str(S.SCOTT_EMAIL))) errors.push('SETTINGS: MODE is "prod" but SCOTT_EMAIL is empty or invalid.');
if (MODE === 'prod' && !/^https:\/\//.test(str(S.SITE_BASE_URL))) errors.push('SETTINGS: MODE is "prod" but SITE_BASE_URL is not set.');

// ---------- tasks
const taskRows = readSheet('Read tasks', 'Sheet "tasks"');
if (taskRows) {
  const withId = taskRows.filter(r => str(r.task_id));
  if (!withId.length) errors.push('Sheet "tasks": no rows with a task_id.');
  else {
    for (const col of ['task_id', 'owners', 'status', 'due_date', 'title_en_CA']) {
      if (!withId.some(r => Object.prototype.hasOwnProperty.call(r, col))) errors.push('Sheet "tasks": column "' + col + '" not found.');
    }
  }
}
const tasks = (taskRows || []).filter(r => str(r.task_id)).map(r => ({
  task_id: str(r.task_id),
  title_en_CA: str(r.title_en_CA),
  title_pt_BR: str(r.title_pt_BR),
  owners: str(r.owners),
  status: str(r.status).toLowerCase(),
  due_raw: str(r.due_date),
  due_date: toISODate(r.due_date),
}));
for (const t of tasks) if (t.due_raw && !t.due_date) errors.push('Sheet "tasks": ' + t.task_id + ' has an unreadable due_date ("' + t.due_raw + '").');

// ---------- latest weekly_snapshots row (most recent snapshot_date; on a tie, the lower row)
const snapRows = readSheet('Read weekly_snapshots', 'Sheet "weekly_snapshots"');
let snapshot = null, kpi = null;
if (snapRows) {
  const valid = snapRows
    .map((r, i) => ({ r, i, sd: toISODate(r.snapshot_date), ws: toISODate(r.week_start) }))
    .filter(x => x.sd && x.ws);
  valid.sort((a, b) => (a.sd === b.sd ? b.i - a.i : (a.sd < b.sd ? 1 : -1)));
  if (!valid.length) errors.push('Sheet "weekly_snapshots": no row with a valid snapshot_date and week_start.');
  else {
    const pick = valid[0];
    snapshot = {
      snapshot_date: pick.sd,
      week_start: pick.ws,
      how_its_going_status: str(pick.r.how_its_going_status),
      executing_text_en_CA: str(pick.r.executing_text_en_CA),
      how_its_going_text_en_CA: str(pick.r.how_its_going_text_en_CA),
      what_to_change_text_en_CA: str(pick.r.what_to_change_text_en_CA),
    };
    try {
      kpi = JSON.parse(str(pick.r.kpi_json) || 'null');
      if (!kpi || typeof kpi !== 'object' || Array.isArray(kpi)) { kpi = null; errors.push('weekly_snapshots (' + pick.ws + '): kpi_json is empty or not an object.'); }
    } catch (e) { errors.push('weekly_snapshots (' + pick.ws + '): kpi_json is not valid JSON.'); }
    if (!['Green', 'Yellow', 'Red', 'Gray'].includes(snapshot.how_its_going_status)) errors.push('weekly_snapshots (' + pick.ws + '): how_its_going_status is "' + snapshot.how_its_going_status + '".');
    if (!snapshot.how_its_going_text_en_CA) errors.push('weekly_snapshots (' + pick.ws + '): how_its_going_text_en_CA is empty.');
    const hasTaskLists = kpi && kpi.tasks && typeof kpi.tasks === 'object';
    if (!hasTaskLists && (!snapshot.executing_text_en_CA || !snapshot.what_to_change_text_en_CA)) errors.push('weekly_snapshots (' + pick.ws + '): no kpi.tasks and the English box texts are empty.');
  }
}

// ---------- dates
const now = DateTime.now().setZone(TZ);
const today = now.toISODate();
const monday = now.startOf('week');            // Luxon weeks start on Monday
const sunday = monday.plus({ days: 6 }).toISODate();
const maxAge = Number(S.MAX_SNAPSHOT_AGE_DAYS) || 8;
if (snapshot) {
  const age = Math.round(now.startOf('day').diff(DateTime.fromISO(snapshot.snapshot_date, { zone: TZ }), 'days').days);
  if (age > maxAge) errors.push('weekly_snapshots: the latest snapshot is from ' + snapshot.snapshot_date + ' (' + age + ' days old, limit ' + maxAge + '). Did workflow B run?');
}
const hoursWeek = snapshot ? DateTime.fromISO(snapshot.week_start, { zone: TZ }).toFormat("kkkk-'W'WW") : '';

return [{ json: {
  ok: errors.length === 0,
  errors,
  mode: MODE,
  today, week_monday: monday.toISODate(), week_sunday: sunday,
  hours_week: hoursWeek,
  snapshot, kpi, tasks,
} }];

// Build email: Scott's open tasks + the Home boxes + hours of the last cycle.
// Output: { ok, errors, to, cc, subject, html, text, raw } — raw is the MIME
// message (multipart/alternative: text + HTML) for the Gmail API.
// Uses only data from the sheets (Prepare data) and the timelog webhook (Get hours).
const S = $('SETTINGS').first().json;
const P = $('Prepare data').first().json;
const str = (v) => (v === null || v === undefined) ? '' : String(v).trim();
const errors = (P.errors || []).slice();
const isNum = (n) => typeof n === 'number' && isFinite(n);

// ---------- hours (same call as the dashboard: public_totals, week of the snapshot)
let hours = null;
{
  let h = null;
  try { h = $('Get hours').first().json; } catch (e) { h = null; }
  if (!h) errors.push('Hours: the timelog webhook did not answer.');
  else if (h.error) errors.push('Hours: timelog webhook failed (' + str(typeof h.error === 'object' ? (h.error.message || JSON.stringify(h.error)) : h.error).slice(0, 200) + ').');
  else if (h.ok !== true || !isNum(h.total_week_hours)) errors.push('Hours: unexpected answer from the timelog webhook.');
  else if (P.hours_week && h.week && h.week !== P.hours_week) errors.push('Hours: asked for ' + P.hours_week + ' but got ' + h.week + '.');
  else hours = h;
}

// ---------- formatting helpers (English, Canada-style short dates: "Nov 25")
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
function short(iso) { const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(str(iso)); return m ? MONTHS[+m[2] - 1] + ' ' + (+m[3]) : ''; }
function esc(s) { return str(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function oneLine(s) { return str(s).replace(/\s+/g, ' ').trim(); }
function fmtH(n) { return (Math.round(n * 10) / 10).toString() + ' h'; }
const splitLines = (s) => str(s).split('\n').map(x => x.trim()).filter(Boolean);
const norm = (s) => str(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();

// ---------- 1. Scott's open tasks
const OWNER = norm(S.SCOTT_NAME || 'Scott');
const CLOSED = str(S.CLOSED_STATUSES || 'done,frozen,dropped').split(',').map(norm).filter(Boolean);
const STATUS_LABEL = { backlog: 'Not started', next: 'Up next', doing: 'In progress', blocked: 'Blocked' };
const today = P.today, sunday = P.week_sunday;
const mine = (P.tasks || [])
  .filter(t => t.owners.split(',').map(norm).includes(OWNER))   // exact name per comma-separated part
  .filter(t => !CLOSED.includes(t.status))
  .map(t => {
    const d = t.due_date;
    const kind = !d ? 'none' : d < today ? 'overdue' : d <= sunday ? 'soon' : 'later';
    return Object.assign({}, t, {
      kind,
      title: oneLine(t.title_en_CA || t.title_pt_BR || t.task_id),
      status_label: STATUS_LABEL[t.status] || (t.status ? t.status.charAt(0).toUpperCase() + t.status.slice(1) : '—'),
      due_label: kind === 'none' ? 'No deadline' : kind === 'overdue' ? 'OVERDUE · was due ' + short(d) : 'Due ' + short(d),
    });
  });
const rank = { overdue: 0, soon: 1, later: 1, none: 2 };
mine.sort((a, b) => rank[a.kind] - rank[b.kind] || (a.due_date < b.due_date ? -1 : a.due_date > b.due_date ? 1 : 0) || a.task_id.localeCompare(b.task_id));
const nOver = mine.filter(t => t.kind === 'overdue').length;
const nSoon = mine.filter(t => t.kind === 'soon').length;
const nNone = mine.filter(t => t.kind === 'none').length;
const countsLine = nOver + ' overdue · ' + nSoon + ' due this week · ' + nNone + ' no deadline';

// ---------- 2. the Home boxes (same rules as site/index.html, English texts)
const snap = P.snapshot || {};
const kpi = P.kpi || {};
const T = kpi.tasks && typeof kpi.tasks === 'object' ? kpi.tasks : null;
const arr = (x) => Array.isArray(x) ? x : [];
const item = (id) => (T && T.items && T.items[id]) || {};
const titleOf = (id) => oneLine(item(id).title_en_CA || item(id).title_pt_BR || id);
function teamNames() { const n = {}; arr(T && T.team_needs).forEach(p => { const k = str(p && p.person).toLowerCase(); if (k) n[k] = true; }); return n; }
function bareTitle(id) {   // "Scott: ask…" -> "Ask…" when every name before ":" is in team_needs
  const t = titleOf(id), m = t.match(/^([^:]{1,80}):\s+(\S[\s\S]*)$/);
  if (!m) return t;
  const names = teamNames(), parts = m[1].split(/\s*(?:,|&|\be\b|\band\b)\s*/i).filter(Boolean);
  if (!parts.length || !parts.every(p => names[p.trim().toLowerCase()])) return t;
  return m[2].charAt(0).toLocaleUpperCase() + m[2].slice(1);
}
let execLines, howLines, changeLines;
if (T) {
  const ex = T.executing || {}, ws = str(kpi.week_start), we = str(kpi.week_end);
  execLines = arr(ex.this_week).map(id => { const d = str(item(id).due_date); return (d && ws && we && d >= ws && d <= we ? 'This week: ' : '') + bareTitle(id); })
    .concat(arr(ex.next_week).map(id => 'Next week: ' + bareTitle(id)));
  changeLines = arr(T.to_change).map(id => {
    const it = item(id), why = [];
    if (it.status === 'blocked') why.push('Blocked');
    if (it.due_date && it.due_date < str(T.base_date) && it.status !== 'done') why.push('Late since ' + short(it.due_date));
    if (it.change_note) why.push(oneLine(it.change_note));
    return titleOf(id) + (why.length ? ' (' + why.join(' · ') + ')' : '');
  });
  const c = T.cycle || {}, g = T.gtm_original || {}, late = isNum(T.late_count) ? T.late_count : 0;
  howLines = [splitLines(snap.how_its_going_text_en_CA)[0] || ''].filter(Boolean);
  if (isNum(c.done) && isNum(c.total)) howLines.push(c.done + ' of ' + c.total + ' in the cycle · ' + late + ' late');
  if (T.forced_color && str(T.forced_reason)) howLines.push('Reason: ' + oneLine(T.forced_reason));
  else if (isNum(g.done_pct) && isNum(g.expected_pct)) howLines.push('Original GTM plan: ' + g.done_pct + '% done, ' + g.expected_pct + '% expected by ' + short(T.cycle_end));
} else {
  execLines = splitLines(snap.executing_text_en_CA);
  howLines = splitLines(snap.how_its_going_text_en_CA);
  changeLines = splitLines(snap.what_to_change_text_en_CA);
}
const MAX = Number(S.MAX_BULLETS) || 3;
function cap(lines) {
  const l = lines.length ? lines : ['Nothing to list.'];
  return { shown: l.slice(0, MAX), more: Math.max(0, l.length - MAX) };
}
const STATUS = {
  Green: { word: 'Green', dot: '#1f8a4c' }, Yellow: { word: 'Yellow', dot: '#b7791f' },
  Red: { word: 'Red', dot: '#c53030' }, Gray: { word: 'Grey', dot: '#718096' },
};
const st = STATUS[snap.how_its_going_status] || STATUS.Gray;
const boxes = [
  { title: 'What we are working on', ...cap(execLines) },
  { title: 'How it is going', status: st, ...cap(howLines) },
  { title: 'What needs to change', ...cap(changeLines) },
];

// ---------- 3. hours line
let hoursText = '';
if (hours) {
  const ws = snap.week_start, we = ws ? DateTime.fromISO(ws).plus({ days: 6 }).toISODate() : '';
  const range = short(ws) + ' – ' + short(we);
  const groups = arr(hours.groups).length ? arr(hours.groups) : arr(hours.rows);
  const parts = groups.filter(gp => isNum(gp.week_hours) && gp.week_hours > 0).map(gp => (str(gp.name_en) || 'Other') + ' ' + fmtH(gp.week_hours));
  hoursText = hours.total_week_hours > 0
    ? 'Hours last cycle (' + range + '): ' + fmtH(hours.total_week_hours) + ' total' + (parts.length ? ' · ' + parts.join(' · ') : '')
    : 'Hours last cycle (' + range + '): no hours logged for this cycle.';
}

// ---------- recipients and subject
const MODE = P.mode;
const test = MODE !== 'prod';
const to = test ? str(S.TEST_EMAIL) : str(S.SCOTT_EMAIL);
const cc = !test && S.CC_ME_IN_PROD === true ? str(S.TEST_EMAIL) : '';
const n = mine.length;
const subject = (test ? '[TEST] ' : '') + 'GTM weekly update – week of ' + short(P.week_monday) + ' – ' +
  (n === 0 ? 'no open tasks for you' : n + ' open task' + (n === 1 ? '' : 's') + ' for you');
const url = /^https:\/\//.test(str(S.SITE_BASE_URL)) ? str(S.SITE_BASE_URL) : '';

// ---------- HTML (light theme, inline CSS, 600px, system font)
const FONT = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const C = { text: '#1a202c', muted: '#5a6473', line: '#e2e8f0', accent: '#2b6cb0', boxBg: '#f0f6fc',
  redText: '#b42318', redBg: '#fdecea', yelText: '#8a5a00', yelBg: '#fff6db' };
function taskRowHtml(t) {
  const due = t.kind === 'overdue'
    ? '<span style="display:inline-block;padding:2px 6px;border-radius:4px;background:' + C.redBg + ';color:' + C.redText + ';font-weight:700;white-space:nowrap;">OVERDUE</span>' +
      '<br><span style="color:' + C.redText + ';white-space:nowrap;">was due ' + esc(short(t.due_date)) + '</span>'
    : t.kind === 'soon'
      ? '<span style="display:inline-block;padding:2px 6px;border-radius:4px;background:' + C.yelBg + ';color:' + C.yelText + ';font-weight:600;white-space:nowrap;">' + esc(t.due_label) + '</span>'
      : '<span style="color:' + C.muted + ';">' + esc(t.due_label) + '</span>';
  const stCol = t.status === 'blocked' ? 'color:' + C.redText + ';font-weight:600;' : 'color:' + C.text + ';';
  return '<tr>' +
    '<td style="padding:8px 8px 8px 0;border-top:1px solid ' + C.line + ';vertical-align:top;">' + esc(t.title) +
      '<div style="font-size:12px;color:' + C.muted + ';">' + esc(t.task_id) + '</div></td>' +
    '<td style="padding:8px;border-top:1px solid ' + C.line + ';vertical-align:top;width:34%;font-size:13px;">' + due + '</td>' +
    '<td style="padding:8px 0 8px 8px;border-top:1px solid ' + C.line + ';vertical-align:top;width:18%;font-size:13px;' + stCol + '">' + esc(t.status_label) + '</td></tr>';
}
const tasksHtml = n === 0
  ? '<p style="margin:0;font-size:15px;">You have no open tasks this week.</p>'
  : '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;font-size:14px;color:' + C.text + ';">' +
    '<tr><th align="left" style="padding:0 8px 6px 0;font-size:12px;color:' + C.muted + ';font-weight:600;">Task</th>' +
    '<th align="left" style="padding:0 8px 6px;font-size:12px;color:' + C.muted + ';font-weight:600;">Deadline</th>' +
    '<th align="left" style="padding:0 0 6px 8px;font-size:12px;color:' + C.muted + ';font-weight:600;">Status</th></tr>' +
    mine.map(taskRowHtml).join('') + '</table>';
function boxHtml(b) {
  const badge = b.status ? ' <span style="font-size:13px;font-weight:600;color:' + b.status.dot + ';">&#9679; ' + esc(b.status.word) + '</span>' : '';
  return '<h3 style="margin:20px 0 6px;font-size:15px;color:' + C.text + ';">' + esc(b.title) + badge + '</h3>' +
    '<ul style="margin:0;padding-left:20px;font-size:14px;line-height:1.5;color:' + C.text + ';">' +
    b.shown.map(l => '<li style="margin:0 0 4px;">' + esc(l) + '</li>').join('') + '</ul>' +
    (b.more ? '<p style="margin:2px 0 0 20px;font-size:13px;color:' + C.muted + ';">+' + b.more + ' more on the dashboard</p>' : '');
}
const button = url
  ? '<a href="' + esc(url) + '" style="display:inline-block;padding:11px 20px;background:' + C.accent + ';color:#ffffff;text-decoration:none;border-radius:6px;font-weight:600;font-size:15px;">Open the dashboard</a>'
  : '<p style="margin:0;font-size:13px;color:' + C.redText + ';">[TEST] SITE_BASE_URL is not set, so the dashboard link is missing.</p>';
const html = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>' + esc(subject) + '</title></head>' +
  '<body style="margin:0;padding:0;background:#ffffff;">' +
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#ffffff;"><tr><td align="center" style="padding:16px;">' +
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;font-family:' + FONT + ';color:' + C.text + ';">' +
  '<tr><td style="font-size:15px;line-height:1.5;">' +
  '<p style="margin:0 0 6px;">Hi Scott,</p>' +
  '<p style="margin:0 0 16px;">Here is your weekly GTM update: your open tasks first, then a short summary of the week.</p>' +
  '<div style="background:' + C.boxBg + ';border-left:4px solid ' + C.accent + ';border-radius:4px;padding:14px 16px;">' +
  '<h2 style="margin:0 0 10px;font-size:17px;color:' + C.text + ';">Your open tasks</h2>' + tasksHtml +
  (n ? '<p style="margin:10px 0 0;font-size:13px;color:' + C.muted + ';">' + esc(countsLine) + '</p>' : '') +
  '</div>' +
  '<h2 style="margin:24px 0 0;font-size:17px;">Summary of the week</h2>' +
  boxes.map(boxHtml).join('') +
  '<p style="margin:20px 0 0;font-size:13px;color:' + C.muted + ';">' + esc(hoursText) + '</p>' +
  '<p style="margin:20px 0;">' + button + '</p>' +
  '<p style="margin:0;">Best,<br>Rafael</p>' +
  '</td></tr></table></td></tr></table></body></html>';

// ---------- plain text
const text = [
  'Hi Scott,', '',
  'Here is your weekly GTM update: your open tasks first, then a short summary of the week.', '',
  'YOUR OPEN TASKS',
  ...(n === 0 ? ['You have no open tasks this week.'] : mine.map(t => '- ' + t.title + ' (' + t.task_id + ') | ' + t.due_label + ' | ' + t.status_label)),
  ...(n ? [countsLine] : []), '',
  'SUMMARY OF THE WEEK',
  ...boxes.flatMap(b => ['', b.title + (b.status ? ' (' + b.status.word + ')' : ''), ...b.shown.map(l => '- ' + l), ...(b.more ? ['  +' + b.more + ' more on the dashboard'] : [])]),
  '', hoursText, '',
  'Open the dashboard: ' + (url || '(link not set)'), '',
  'Best,', 'Rafael',
].join('\n');

// ---------- MIME (multipart/alternative) for the Gmail API
function b64(s) {   // UTF-8 -> base64, no Buffer needed
  const bytes = unescape(encodeURIComponent(s)), A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes.charCodeAt(i), b = bytes.charCodeAt(i + 1), c = bytes.charCodeAt(i + 2);
    const t = (a << 16) | ((b || 0) << 8) | (c || 0);
    out += A[(t >> 18) & 63] + A[(t >> 12) & 63] + (i + 1 < bytes.length ? A[(t >> 6) & 63] : '=') + (i + 2 < bytes.length ? A[t & 63] : '=');
  }
  return out;
}
const wrap76 = (s) => s.replace(/.{1,76}/g, '$&\r\n');
const boundary = 'dcti-' + Date.now().toString(36);
const mime = [
  'To: ' + to, ...(cc ? ['Cc: ' + cc] : []),
  'Subject: =?UTF-8?B?' + b64(subject) + '?=',
  'MIME-Version: 1.0',
  'Content-Type: multipart/alternative; boundary="' + boundary + '"', '',
  '--' + boundary, 'Content-Type: text/plain; charset=UTF-8', 'Content-Transfer-Encoding: base64', '', wrap76(b64(text)),
  '--' + boundary, 'Content-Type: text/html; charset=UTF-8', 'Content-Transfer-Encoding: base64', '', wrap76(b64(html)),
  '--' + boundary + '--', '',
].join('\r\n');
